const crypto = require('crypto');
const event = $json.body ?? $json;
const timestamp = String($json.headers?.['x-lendloop-timestamp'] ?? '');
const signature = String($json.headers?.['x-lendloop-signature'] ?? '');
const now = Math.floor(Date.now() / 1000);
if (!/^\d{10}$/.test(timestamp) || Math.abs(now - Number(timestamp)) > 300) throw new Error('Rejected stale or invalid LendLoop timestamp');
const body = JSON.stringify(event);
const expected = crypto.createHmac('sha256', $env.LENDLOOP_N8N_SECRET).update(`${timestamp}.${body}`).digest('hex');
if (!/^[a-f0-9]{64}$/.test(signature)) throw new Error('Invalid LendLoop HMAC signature');
const suppliedBuffer = Buffer.from(signature, 'hex');
const expectedBuffer = Buffer.from(expected, 'hex');
if (!crypto.timingSafeEqual(suppliedBuffer, expectedBuffer)) throw new Error('Invalid LendLoop HMAC signature');
if (typeof event.loanId !== 'string' || !event.loanId || typeof event.toolName !== 'string' || !event.toolName || typeof event.startDate !== 'string' || typeof event.endDate !== 'string' || !['requested', 'approved', 'declined', 'returned'].includes(event.event) || event.status !== event.event || !Array.isArray(event.recipients) || event.recipients.length === 0 || event.recipients.some((email) => typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))) throw new Error('Invalid request event fields or recipient addresses');
const labels = { requested: 'New borrowing request', approved: 'Borrowing request approved', declined: 'Borrowing request declined', returned: 'Tool marked as returned' };
const subject = `LendLoop: ${labels[event.event]}`;
const message = `Hello,\n\n${labels[event.event]}.\n\nTool: ${event.toolName}\nDates: ${event.startDate} to ${event.endDate}\nRequest: ${event.loanId}\n\nOpen LendLoop to view the details.`;
return { json: { to: event.recipients.join(', '), subject, message } };
